INSERT INTO modules(id,name,emoji,signal,summary,safety,sort_order) VALUES
('led','LED đơn','💡','Digital / PWM · mức 3,3V','Biến tín hiệu điện thành ánh sáng.','Luôn dùng điện trở hạn dòng phù hợp; không nối LED trực tiếp vào GPIO.',1),
('button','Nút nhấn','🔘','Digital Input · INPUT_PULLUP','Nhận biết hành động nhấn và nhả.','GPIO34/35 không có pull-up nội; bài tập nút phải dùng chân phù hợp.',2),
('pot','Biến trở 10kΩ','🎚️','ADC · 0–4095 minh họa','Đổi vị trí núm thành giá trị số ADC.','Không đưa điện áp cao hơn giới hạn ADC; chỉ cấp 3,3V theo hồ sơ.',3),
('ldr','Cảm biến ánh sáng AO','☀️','ADC · ánh sáng tương đối','Đọc cường độ sáng bằng điện áp analog.','Không mặc định đầu AO 5V an toàn cho ESP32; cần kiểm tra module.',4),
('buzzer','Còi chủ động + driver','🔔','Digital Output qua driver','Phát cảnh báo bằng lệnh bật/tắt.','Dùng driver và nguồn phù hợp; không nối tải lớn thẳng GPIO.',5),
('servo','Servo SG90 (mẫu)','⚙️','Servo pulse · khoảng 50Hz','Điều khiển góc bằng độ rộng xung.','Dùng nguồn ngoài đủ dòng, chung GND và kiểm tra giới hạn góc.',6),
('bh1750','BH1750 (I²C)','🌤️','I²C · SDA21 + SCL22','Đo độ rọi gần đúng theo đơn vị lux.','Xác minh mức áp, pull-up và địa chỉ I²C thực tế.',7);
INSERT INTO lessons(id,title,emoji,level,duration_minutes,topic,description,module_ids,goals,question,choices,correct_choice,reason,recipe,experiment,takeaway,default_code,sort_order) VALUES
('led-on','Thắp sáng LED đầu tiên','💡',1,10,'GPIO Digital Output','Hiểu HIGH/LOW và biến một chân ra thành ánh sáng.','["led"]','["Phân biệt chân nguồn và GPIO","Đấu LED đúng cực qua điện trở","Điều khiển bật/tắt bằng digitalWrite()"]','Vì sao LED cần điện trở hạn dòng?','["Để giới hạn dòng qua LED","Để làm tăng điện áp GPIO","Để đổi GPIO thành ADC"]',0,'Điện trở hạn dòng giúp bảo vệ LED và chân GPIO khỏi dòng quá lớn.',E'KHI khởi động\n  đặt GPIO23 thành OUTPUT\nSAU ĐÓ\n  bật LED (HIGH)\n  đợi 1 giây\n  tắt LED (LOW)','Gạt công tắc và quan sát mức logic.','Khi chân là OUTPUT, HIGH/LOW quyết định trạng thái theo cách đấu active-high.',E'const int LED_PIN = 23;\nvoid setup() { pinMode(LED_PIN, OUTPUT); }\nvoid loop() { digitalWrite(LED_PIN, HIGH); }',1),
('blink','LED nhấp nháy','✨',1,12,'Vòng lặp & delay','Làm đèn nhấp nháy đều theo thời gian.','["led"]','["Hiểu loop() và delay()","Thiết lập nhịp bật/tắt","So sánh thời gian sáng và tắt"]','Lệnh delay(500) làm gì?','["Tạm dừng khoảng 500 mili-giây","Đặt điện áp GPIO thành 500V","Đọc ADC 500 lần"]',0,'delay(500) tạm dừng khoảng nửa giây trong Arduino.',E'LẶP LIÊN TỤC\n  bật LED\n  đợi 500 ms\n  tắt LED\n  đợi 500 ms','Đổi thời gian chờ và quan sát chu kỳ.','Lệnh trong loop() được thực hiện lặp lại liên tục.',E'const int LED_PIN = 23;\nvoid setup() { pinMode(LED_PIN, OUTPUT); }\nvoid loop() {\n  digitalWrite(LED_PIN, HIGH); delay(500);\n  digitalWrite(LED_PIN, LOW); delay(500);\n}',2),
('button','Đọc nút nhấn','🔘',1,15,'GPIO Digital Input','Phân biệt tín hiệu nhấn và nhả.','["button"]','["Cấu hình INPUT_PULLUP","Đọc digitalRead()","Giải thích vì sao nhấn đọc LOW"]','Khi dùng INPUT_PULLUP và nút nối GND, lúc nhấn ta đọc được gì?','["HIGH","LOW","Giá trị ADC bất kỳ"]',1,'Nút nhấn nối chân xuống GND nên mức logic trở thành LOW.',E'KHI khởi động\n  cấu hình nút là INPUT_PULLUP\nLẶP LIÊN TỤC\n  đọc giá trị nút','Nhấn nút ảo, xem mức logic đổi HIGH → LOW.','INPUT_PULLUP tránh tín hiệu thả nổi; nhấn thường tương ứng LOW.',E'const int BUTTON_PIN = 18;\nvoid setup() { pinMode(BUTTON_PIN, INPUT_PULLUP); Serial.begin(115200); }\nvoid loop() { Serial.println(digitalRead(BUTTON_PIN)); delay(50); }',3),
('pwm','Điều chỉnh độ sáng LED','🎚️',2,18,'PWM Duty Cycle','Thay đổi độ sáng nhờ điều chế độ rộng xung.','["led"]','["Hiểu duty cycle 0–100%","Phân biệt PWM và điện áp DC","Điều khiển ledcWrite() trên ESP32"]','Khi duty cycle từ 20% lên 80%, LED thường thế nào?','["Sáng hơn","Tắt hẳn","Đổi màu tự động"]',0,'Duty cycle lớn hơn làm thời gian bật nhiều hơn, LED thường sáng hơn.',E'LẶP LIÊN TỤC\n  thay đổi duty PWM\n  quan sát độ sáng','Kéo độ sáng 10% → 50% → 90%.','PWM thay đổi độ sáng trung bình mà không đổi chân phần cứng.',E'const int LED_PIN = 25;\nvoid setup() { ledcAttach(LED_PIN, 5000, 8); }\nvoid loop() { ledcWrite(LED_PIN, 204); delay(100); }',4),
('pot','Đọc biến trở bằng ADC','🎛️',2,20,'Analog & ADC','Tìm hiểu cách biến điện áp thành con số.','["pot"]','["Nhận diện chân ADC1","Hiểu giá trị 12-bit","Quan sát biến thiên khi xoay biến trở"]','Bộ ADC dùng để làm gì?','["Chuyển điện áp analog thành số","Tạo dòng vô hạn","Nạp firmware"]',0,'ADC chuyển tín hiệu điện áp tương tự thành giá trị số.',E'LẶP LIÊN TỤC\n  đọc chân ADC\n  hiển thị số 0–4095','Dịch núm ảo và xem chỉ số ADC.','Một tín hiệu vật lý liên tục có thể được chương trình đo và xử lý.',E'const int POT_PIN = 34;\nvoid setup() { Serial.begin(115200); }\nvoid loop() { Serial.println(analogRead(POT_PIN)); delay(100); }',5),
('ldr','Đo ánh sáng môi trường','☀️',2,20,'Cảm biến Analog','Tạo thí nghiệm che và chiếu sáng cảm biến.','["ldr"]','["Kết nối AO với ADC1","Ghi nhận dữ liệu đo","Tự xác định chiều tăng/giảm ADC"]','Có thể khẳng định mọi module LDR đều tăng ADC khi sáng không?','["Có, tất cả đều giống nhau","Không, tùy mạch chia áp","Chỉ khi dùng PWM"]',1,'Cực tính mạch chia áp quyết định ADC tăng hay giảm; cần hiệu chuẩn.',E'LẶP LIÊN TỤC\n  lấy mẫu ánh sáng ADC\n  ghi dữ liệu','Thay đổi ánh sáng và ghi lại các lần đo.','Module cảm biến có cách quy đổi khác nhau; phải kiểm chứng.',E'const int LDR_PIN = 35;\nvoid setup() { Serial.begin(115200); }\nvoid loop() { Serial.println(analogRead(LDR_PIN)); delay(150); }',6),
('buzzer','Tạo âm báo cảnh báo','🔔',2,18,'GPIO & Driver','Hiểu vì sao tải bên ngoài thường cần mạch driver.','["buzzer"]','["Nhận diện còi chủ động","Phân biệt GPIO và nguồn tải","Điều khiển còi qua MOSFET"]','Vì sao còi công suất lớn không nên nối trực tiếp GPIO?','["Vì GPIO giới hạn dòng","Vì không có âm thanh trong không khí","Vì GPIO chỉ làm I²C"]',0,'Chân GPIO có giới hạn dòng, nên dùng driver phù hợp.',E'KHI bật\n  đặt chân driver = HIGH\nKHI tắt\n  đặt về LOW','Bật/tắt còi ảo; mạch thật cần kiểm tra driver.','Vi điều khiển điều khiển tín hiệu, driver cấp năng lượng cho tải.',E'const int BUZZER_PIN = 26;\nvoid setup() { pinMode(BUZZER_PIN, OUTPUT); }\nvoid loop() { digitalWrite(BUZZER_PIN, HIGH); delay(300); digitalWrite(BUZZER_PIN, LOW); delay(700); }',7),
('bh1750','Đọc BH1750 qua I²C','🌤️',3,25,'I²C SDA/SCL','Trao đổi dữ liệu với cảm biến số.','["bh1750"]','["Phân biệt SDA và SCL","Hiểu địa chỉ I²C","Đọc giá trị lux trên BH1750"]','BH1750 cần những đường tín hiệu nào?','["Chỉ SDA","SDA và SCL","Chỉ một chân ADC"]',1,'I²C cần SDA và SCL, kèm nguồn và GND.',E'KHỞI TẠO I²C: SDA21, SCL22\nĐỌC BH1750 tại 0x23','Dịch mức lux ảo; chạy thật cần đúng cảm biến.','Một bus I²C có thể nối nhiều module nếu địa chỉ và điện áp phù hợp.',E'#include <Wire.h>\nvoid setup() { Wire.begin(21, 22); }\nvoid loop() { Wire.requestFrom((uint8_t)0x23, (uint8_t)2); delay(200); }',8),
('button-led','Nhấn nút bật LED','🪄',3,25,'Input → Output','Biến hành động nhấn thành phản hồi vật lý.','["button","led"]','["Kết hợp 2 chân GPIO","Đọc input và ra quyết định","Hiểu if/else"]','Nếu INPUT_PULLUP đọc LOW nghĩa là gì trong sơ đồ này?','["Nút đang nhấn","Nút chưa nhấn","LED bị cháy"]',0,'Khi nhấn, công tắc kéo chân input xuống GND.',E'NẾU nút LOW\n  BẬT LED\nNGƯỢC LẠI\n  TẮT LED','Nhấn giữ nút để quan sát LED.','Đọc đầu vào và xử lý điều kiện là nền tảng tự động hóa.',E'const int BUTTON_PIN=18, LED_PIN=23;\nvoid setup(){ pinMode(BUTTON_PIN,INPUT_PULLUP); pinMode(LED_PIN,OUTPUT); }\nvoid loop(){ digitalWrite(LED_PIN,digitalRead(BUTTON_PIN)==LOW?HIGH:LOW); }',9),
('night','Đèn ngủ theo ánh sáng','🌙',3,30,'Cảm biến & Tự động hóa','Bật đèn khi trời tối bằng cảm biến analog.','["ldr","led"]','["Đọc LDR từ ADC1","Đặt ngưỡng điều khiển","Hiệu chuẩn chiều tín hiệu thực tế"]','Khi chuyển từ sáng sang tối, nên làm gì trước khi chọn điều kiện?','["Hiệu chuẩn xem ADC tăng hay giảm","Đặt PWM 100% mãi mãi","Bỏ qua cảm biến"]',0,'Phải xác định chiều biến thiên ADC trước khi viết điều kiện.',E'ĐỌC ADC ánh sáng\nNẾU ADC < ngưỡng\n  bật LED\nNGƯỢC LẠI tắt LED','Thay đổi ánh sáng và theo dõi đèn tự bật.','Cảm biến + điều kiện + đầu ra tạo nên thiết bị thông minh.',E'const int LDR_PIN=35, LED_PIN=25;\nvoid setup(){ pinMode(LED_PIN,OUTPUT); }\nvoid loop(){ int light=analogRead(LDR_PIN); digitalWrite(LED_PIN,light<1800?HIGH:LOW); delay(100); }',10);
INSERT INTO curriculum_projects(id,title,emoji,difficulty,duration_minutes,description,module_ids,sort_order) VALUES
('night','Đèn ngủ thông minh','🌙','Dễ',45,'Điều chỉnh đèn LED theo ánh sáng môi trường.','["ldr","led"]',1),
('traffic','Đèn giao thông mini','🚦','Trung bình',50,'Tự thiết kế chu kỳ đèn đỏ, vàng, xanh.','["led","led","led"]',2),
('access','Nút bấm điều khiển đèn','🔘','Dễ',35,'Tạo bộ đèn chỉ sáng khi nhấn nút.','["button","led"]',3),
('servo','Cánh tay servo mini','🦾','Nâng cao',60,'Khảo sát góc quay và xung điều khiển servo.','["servo"]',4);
